234	// Reads chunks from a stream until it ends or holds more than MAX_BYTES.
235	async function readCapped(stream) {
236	  const chunks = [];
237	  let total = 0;
238	  try {
239	    for await (const chunk of stream) {
240	      chunks.push(chunk);
241	      total += chunk.length;
242	      if (total > MAX_BYTES) return null;
243	    }
244	  } finally {
245	    stream.destroy();
246	  }
247	  return Buffer.concat(chunks);
