278	// Depth of valid JSON text, counted without recursion.
279	function jsonDepth(text) {
280	  let depth = 0;
281	  let max = 0;
282	  let inString = false;
283	  for (let i = 0; i < text.length; i++) {
284	    const c = text[i];
285	    if (inString) {
286	      if (c === '\\') i++;
287	      else if (c === '"') inString = false;
288	    } else if (c === '"') {
289	      inString = true;
290	    } else if (c === '[' || c === '{') {
291	      depth++;
292	      if (depth > max) max = depth;
293	    } else if (c === ']' || c === '}') {
