// Runs the suite against each near-miss in a scratch mirror of the project,
// so the originals are never touched: node run.mjs <projectRoot> [filter]
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { spawnSync } from 'node:child_process';

const root = process.argv[2];
const filter = process.argv[3];
const nmDir = path.join(root, '.team/near-miss');
const work = fs.mkdtempSync(path.join(os.tmpdir(), 'nm-work-'));
const copies = fs.readdirSync(nmDir).filter((f) => f.endsWith('.mjs') && (!filter || f.startsWith(`${filter}-`)));

for (const base of copies.sort((a, b) => parseInt(a, 10) - parseInt(b, 10))) {
  const dir = path.join(work, base);
  fs.mkdirSync(dir);
  for (const f of ['jsonpatch.mjs', 'jsonpatch-cli.mjs', 'package.json']) fs.copyFileSync(path.join(root, f), path.join(dir, f));
  fs.cpSync(path.join(root, 'test'), path.join(dir, 'test'), { recursive: true });
  fs.copyFileSync(path.join(nmDir, base), path.join(dir, base.replace(/^\d+-/, '')));
  const r = spawnSync('npm', ['test'], { cwd: dir, encoding: 'utf8', maxBuffer: 256 * 1024 * 1024 });
  const fail = /^# fail (\d+)/m.exec(r.stdout)?.[1] ?? '?';
  const firstLine = fs.readFileSync(path.join(nmDir, base), 'utf8').split('\n')[0];
  process.stdout.write(`${fail === '0' ? 'SURVIVED' : 'killed  '} ${base} fail=${fail} ${firstLine}\n`);
}
fs.rmSync(work, { recursive: true, force: true });

